pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address constant OWNER = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint256 len) public {
        uint256 l = bound(len, 0, 8);

        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(i, block.timestamp)))));
            vals[i] = 0;
        }

        bool ok;
        vm.startPrank(OWNER);
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        if (l == 0) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
